// Feeds the summary model a DELIBERATELY NARROW slice, shaped to the fixed
// structure the summary uses. Handing over the full results object would let
// the model pick any number it liked and present it as a finding.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.results_json);
if (!rows.length) throw new Error('No stored results found for this period - the report workflow should write them before calling this.');

rows.sort((a, b) => String(b.generated_at || '').localeCompare(String(a.generated_at || '')));
const stored = rows[0];
const r = JSON.parse(stored.results_json);
const th = r.themes || {};
const st = r.stats || {};

// The overall score is stored alongside the tables. It is NOT in r.scores,
// which only covers the five segment dimensions.
const o = r.overall_score || null;
const score = o ? {
  nps: o.nps, responses: o.responses, promoters: o.promoters, passives: o.passives, detractors: o.detractors,
  pct_with_text: o.pct_with_text,
  change_since_last_month: o.nps_delta,
  change_is_real: o.delta_moved === true,
} : null;

const find = (dim, group) => (r.scores || []).find((x) => x.dimension === dim && String(x.group) === group) || null;
const pick = (x) => (x ? { group: x.group, nps: x.nps, vs_average: x.vs_average, responses: x.responses, change: x.change } : null);

// Enterprise means the Enterprise TIER ONLY. An earlier summary lumped
// Business in with it, which is a different commercial tier.
const enterprise = pick(find('Enterprise tier', 'Enterprise'));
const cloud = pick(find('Cloud vs self-hosted', 'cloud'));
const selfHosted = pick(find('Cloud vs self-hosted', 'self_hosted'));

// Only movements the code marked significant. A star in the change column is
// the code's verdict, not a judgement the model gets to make.
const movements = (r.scores || [])
  .filter((x) => /\*/.test(String(x.change || '')))
  .map((x) => ({ segment: x.dimension, group: x.group, nps: x.nps, change: x.change, responses: x.responses }));

const independent = (r.findings || [])
  .filter((f) => f.real_effect === 'YES')
  .map((f) => ({ segment: f.dimension, group: f.group, topic: f.topic, direction: f.direction, this_group: f.this_group, everyone_else: f.everyone_else, n: f.responses }));

const payload = {
  period: r.period,
  score,
  top_topics: (r.topics || []).filter((t) => !t.note).slice(0, 4),
  top_requests: (th.request_themes || []).slice(0, 4).map((t) => ({ theme: t.label, mentions: t.mentions, share: t.share_pct + '%' })),
  top_complaints: (th.complaint_themes || []).slice(0, 4).map((t) => ({ theme: t.label, mentions: t.mentions, share: t.share_pct + '%' })),
  enterprise_tier_only: enterprise,
  cloud: cloud,
  self_hosted: selfHosted,
  significant_score_changes: movements,
  independent_segment_differences: independent,
  unassigned_alert: th.alert === true,
  unassigned: th.unassigned || null,
};

console.log('[Summary] ' + r.period + ': NPS ' + (score ? score.nps : 'missing') + ', enterprise ' + (enterprise ? enterprise.nps : 'n/a') + ', ' + movements.length + ' real movements, ' + independent.length + ' independent findings');

return [{ json: {
  period_label: r.period,
  page_id: stored.page_id,
  page_url: stored.page_url,
  promptText: JSON.stringify(payload),
} }];

// Parse defensively. A failed summary must leave the page's placeholder alone
// rather than overwriting it with an error - the report itself is unaffected.
const raw = $json.output ?? $json.text ?? '';
const ctx = $('Build Summary Input').first().json;

let parsed = null, parseError = '';
try {
  parsed = JSON.parse(String(raw).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim());
} catch (e) { parseError = e.message; }

const s = (v) => (typeof v === 'string' ? v.trim() : '');
const oneLiner = parsed ? s(parsed.one_liner) : '';

// The three standing sentences read as one paragraph. worth_noting is optional
// by design and absent most months.
const body = parsed ? [s(parsed.talked_about), s(parsed.enterprise), s(parsed.deployment)].filter(Boolean) : [];
const worthNoting = parsed ? s(parsed.worth_noting) : '';

if (!oneLiner) {
  console.warn('[Summary] no usable summary returned (' + parseError + ') - leaving the placeholder untouched');
  return [{ json: { ok: false, parseError, page_id: ctx.page_id, page_url: ctx.page_url, period_label: ctx.period_label } }];
}

console.log('[Summary] ' + ctx.period_label + ': one-liner + ' + body.length + ' standing sentence(s)' + (worthNoting ? ' + worth noting' : ', nothing unusual'));

return [{ json: {
  ok: true, parseError: '',
  page_id: ctx.page_id, page_url: ctx.page_url, period_label: ctx.period_label,
  one_liner: oneLiner, body, worth_noting: worthNoting,
} }];

// Finds the placeholder paragraph the report workflow left under the Summary
// heading, so the summary lands at the TOP of the page rather than appended to
// the bottom. Matching on the placeholder text rather than on position means an
// edited page does not get its content overwritten.
const parsed = $('Parse Summary').first().json;
if (!parsed.ok) throw new Error('No summary to write: ' + parsed.parseError);

const blocks = ($json.results || []).length ? $json.results : ($json.body && $json.body.results) || $json.results || [];
if (!Array.isArray(blocks) || !blocks.length) throw new Error('Notion returned no blocks for page ' + parsed.page_id);

const textOf = (b) => {
  const t = b && b[b.type];
  const rt = t && t.rich_text;
  return Array.isArray(rt) ? rt.map((x) => (x.plain_text || (x.text && x.text.content) || '')).join('') : '';
};

let target = blocks.find((b) => b.type === 'paragraph' && textOf(b).trim().toLowerCase().startsWith('to be written'));
if (!target) {
  const hIdx = blocks.findIndex((b) => (b.type === 'heading_2' || b.type === 'heading_1') && textOf(b).trim().toLowerCase() === 'summary');
  if (hIdx >= 0) target = blocks.slice(hIdx + 1).find((b) => b.type === 'paragraph');
}
if (!target) throw new Error('Could not find the Summary placeholder on page ' + parsed.page_id + '. It may have been removed.');

const txt = (content, annotations) => ({ type: 'text', text: { content: String(content).slice(0, 2000) }, ...(annotations ? { annotations } : {}) });

// One-liner goes bold into the placeholder itself. The three standing sentences
// follow as a single readable paragraph rather than a list of statistics - the
// bulleted version was accurate and unreadable.
const headline_rich = [txt(parsed.one_liner, { bold: true })];
const detail_blocks = [];
if (parsed.body.length) {
  detail_blocks.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: [txt(parsed.body.join(' '))] } });
}
if (parsed.worth_noting) {
  // A plain paragraph with the pin inline, NOT a callout box. As a callout it
  // outranked the bold headline and read as the main message, when it is the
  // optional aside.
  detail_blocks.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: [txt('\uD83D\uDCCC ' + parsed.worth_noting)] } });
}
detail_blocks.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: [txt('Want the detail? It is all below.', { italic: true })] } });

console.log('[Summary] writing into block ' + target.id + ' on page ' + parsed.page_id);

return [{ json: {
  page_id: parsed.page_id, block_id: target.id,
  headline_rich, detail_blocks,
}}];

// Posted from HERE rather than from the report workflow, because the summary
// does not exist until it has been written. Slack carries the WHOLE summary
// now that it is four short sentences: it is short enough to read in the
// channel, and anything longer belongs in Notion rather than being duplicated.
const p = $('Parse Summary').first().json;
const period = p.period_label || '';
const url = p.page_url || '';

const lines = [];
lines.push(`*NPS monthly* \u00b7 ${period}`);
lines.push('');
lines.push(`*${p.one_liner}*`);

if ((p.body || []).length) {
  lines.push('');
  lines.push(p.body.join(' '));
}

// The optional aside keeps the pin so it reads the same way in both places,
// but stays plain text so it does not outrank the headline.
if (p.worth_noting) {
  lines.push('');
  lines.push(`\uD83D\uDCCC ${p.worth_noting}`);
}

lines.push('');
lines.push(url ? `<${url}|Read the full report>` : '_The full report is in the NPS DB in Notion._');

console.log('[Slack] posting full summary for ' + period + (url ? ' with page link' : ' WITHOUT a page link - page_url was empty'));
return [{ json: { slack_text: lines.join('\n'), period_label: period, page_url: url } }];
